  // STICKER: 50 cents, VAT 21% = 10.5 cents → 10 cents (banker's rounding), total = 60 cents
  // 100 days overdue, fee = 60 * 100 * 0.0004 = 2.4 cents → 2 cents
  const result = lateFee(issued.value, '2026-12-31');

  assert.equal(result, 2);
});

test('lateFee: handles invoice with discount', () => {
