});

test('lateFee: charges per calendar day', () => {
  const invResult = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  assert.equal(invResult.ok, true);
  const issued = issueInvoice(invResult.value, []);

  // Due is 11495 cents
  // 1 day: fee = 11495 * 1 * 0.0004 = 4.598 → 5 cents (banker's rounding: 4.598 rounds to 5)
  const result1 = lateFee(issued.value, '2026-11-01');

  // 2 days: fee = 11495 * 2 * 0.0004 = 9.196 → 9 cents
  const result2 = lateFee(issued.value, '2026-11-02');

  // Verify each additional day adds roughly 4.598 cents
  assert.equal(result1, 5);
  assert.equal(result2, 9);
});

