  const invoices = [issued.value];
  const result = overdueInvoices(invoices, '2026-11-15');

  assert.equal(result.length, 1);
  // DEV-HOUR qty 2: €190.00, VAT 21% = €39.90, total = €229.90 = 22990 cents
  assert.equal(result[0].due, 22990);
});

test('overdueInvoices: subtracts payments from due', () => {
  const invResult = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 2 }],
  });
  assert.equal(invResult.ok, true);
  const issued = issueInvoice(invResult.value, []);

  let inv = issued.value;
  const paymentResult = recordPayment(inv, { amount: 10000, date: '2026-10-15' });
  assert.equal(paymentResult.ok, true);
  inv = paymentResult.value;

  const invoices = [inv];
  const result = overdueInvoices(invoices, '2026-11-15');

  assert.equal(result.length, 1);
  // Total 22990, paid 10000, due 12990
  assert.equal(result[0].due, 12990);
});

test('overdueInvoices: sorts by daysOverdue descending (most overdue first)', () => {
  const inv1Result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  assert.equal(inv1Result.ok, true);
  const inv1Issued = issueInvoice(inv1Result.value, []);

  const inv2Result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-10',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  assert.equal(inv2Result.ok, true);
  const inv2Issued = issueInvoice(inv2Result.value, [inv1Issued.value.number]);

  const invoices = [inv1Issued.value, inv2Issued.value];
  // inv1 due 2026-10-31 (15 days overdue on 2026-11-15)
  // inv2 due 2026-11-09 (6 days overdue on 2026-11-15)
  const result = overdueInvoices(invoices, '2026-11-15');

  assert.equal(result.length, 2);
  assert.equal(result[0].daysOverdue, 15);
  assert.equal(result[1].daysOverdue, 6);
});

test('overdueInvoices: includes partially_paid invoices', () => {
